5	/// Optional manual IP override for the Flux Controller.
6	///
7	/// The primary discovery path is mDNS ([FluxControllerDiscovery]).
8	/// This is only consulted when mDNS times out — useful on networks where
9	/// multicast is blocked or the user is on a different subnet.
10	class ControllerSettings {
11	  const ControllerSettings({required this.host, required this.port});
12	
13	  final String host;
14	  final int    port;
15	
16	  static const _kHost        = 'ctrl_host';
17	  static const _kPort        = 'ctrl_port';
18	  static const _kPsk         = 'ctrl_psk';          // hex32 keyed by controller ID
19	  static const _kDtlsId      = 'ctrl_dtls_id';      // DTLS identity — same as controller ID
20	
21	  static Future<ControllerSettings?> loadManualOverride() async {
22	    final prefs = await SharedPreferences.getInstance();
23	    final host  = prefs.getString(_kHost);
24	    if (host == null || host.isEmpty) return null;
25	    return ControllerSettings(host: host, port: prefs.getInt(_kPort) ?? 5684);
26	  }
27	
28	  /// Returns the stored PSK for the given controller [hostname], or null if
29	  /// no PSK has been configured (plain CoAP — migration phase).
30	  static Future<Uint8List?> loadPsk(String hostname) async {
31	    final prefs = await SharedPreferences.getInstance();
32	    final hex   = prefs.getString('${_kPsk}_$hostname');
33	    if (hex == null || hex.length != 32) return null;
34	    try {
35	      return Uint8List.fromList(List.generate(
36	          16, (i) => int.parse(hex.substring(i * 2, i * 2 + 2), radix: 16)));
37	    } on FormatException catch (_) { return null; }
38	  }
39	
40	  /// True when at least one controller PSK has been stored — i.e. a hub has
41	  /// been set up at some point, even if it is currently unreachable. Lets the
42	  /// UI distinguish "no hub configured yet" from "hub configured but offline".
43	  static Future<bool> hasAnyPsk() async {
44	    final prefs = await SharedPreferences.getInstance();
45	    return prefs.getKeys().any((k) => k.startsWith('${_kPsk}_'));
46	  }
47	
48	  /// Persists a 16-byte [psk] for [hostname].
49	  static Future<void> savePsk(String hostname, Uint8List psk,
50	      {String? dtlsIdentity}) async {
51	    assert(psk.length == 16, 'PSK must be exactly 16 bytes');
52	    final prefs = await SharedPreferences.getInstance();
53	    final hex = psk.map((b) => b.toRadixString(16).padLeft(2, '0')).join();
54	    await prefs.setString('${_kPsk}_$hostname', hex);
55	    if (dtlsIdentity != null) {
56	      await prefs.setString('${_kDtlsId}_$hostname', dtlsIdentity);
57	    }
58	  }
59	
60	  /// Removes the stored PSK for [hostname] (reverts to plain CoAP).
61	  static Future<void> clearPsk(String hostname) async {
62	    final prefs = await SharedPreferences.getInstance();
63	    await prefs.remove('${_kPsk}_$hostname');
64	  }
65	
66	  Future<void> save() async {
67	    final prefs = await SharedPreferences.getInstance();
68	    await prefs.setString(_kHost, host);
69	    await prefs.setInt   (_kPort, port);
70	  }
71	
72	  static Future<void> clear() async {
73	    final prefs = await SharedPreferences.getInstance();
74	    await prefs.remove(_kHost);
75	    await prefs.remove(_kPort);
76	  }
77	}
