9	/// Mutable handle on the Flux Controller connection.
10	///
11	/// Injected as a [ChangeNotifierProvider] so any widget or provider can
12	/// watch for connection changes without restarting the app.
13	///
14	/// The initial service is set in [main] after startup discovery.
15	/// [reconnect] can be called later (e.g. from the settings screen) to
16	/// re-run discovery and swap in a new [FluxCoapService].
17	class HubConnection extends ChangeNotifier {
18	  HubConnection(FluxCoapService? initial) : _service = initial {
19	    unawaited(refreshConfiguredState());
20	  }
21	
22	  FluxCoapService? _service;
23	  bool _hasStoredPsk = false;
24	
25	  FluxCoapService? get service => _service;
26	  bool get isConnected => _service != null;
27	
28	  /// True when a hub has been configured (a PSK is stored), even if the
29	  /// controller is currently unreachable. Lets the UI distinguish "no hub set
30	  /// up yet" from "hub set up but offline" — the latter should not be told to
31	  /// pair a new hub.
32	  bool get hasConfiguredHub => isConnected || _hasStoredPsk;
33	
34	  /// Re-reads whether any controller PSK is stored and notifies listeners if it
35	  /// changed. Call after the add-controller flow saves a PSK.
36	  Future<void> refreshConfiguredState() async {
37	    final has = await ControllerSettings.hasAnyPsk();
38	    if (has != _hasStoredPsk) {
39	      _hasStoredPsk = has;
40	      notifyListeners();
41	    }
42	  }
43	
44	  /// Directly installs a freshly-created service (e.g. after background
45	  /// discovery that completed post-boot) and notifies listeners.
46	  void setService(FluxCoapService svc) {
47	    _service?.dispose();
48	    _service = svc;
49	    notifyListeners();
50	  }
51	
52	  /// Re-runs mDNS discovery (+ manual-IP fallback) and, on success, replaces
53	  /// the active service and notifies listeners.
54	  Future<bool> reconnect() async {
55	    final ep = await FluxControllerDiscovery.discover();
56	    if (ep == null) return false;
57	
58	    _service?.dispose();
59	    _service = FluxCoapService(ep);
60	    notifyListeners();
61	    return true;
62	  }
63	
64	  @override
65	  void dispose() {
66	    _service?.dispose();
67	    super.dispose();
68	  }
69	}
