158	
159	    setState(() => _syncingThread = true);
160	    try {
161	      final result = await ThreadSyncService(svc).ensureInSync();
162	      if (!mounted) return;
163	
164	      final message = switch (result.status) {
165	        ThreadSyncStatus.adopted     => "Using the hub's Thread network ✓",
166	        ThreadSyncStatus.pushed      => 'Thread network sent to the hub ✓',
167	        ThreadSyncStatus.inSync      => 'Thread network already in sync ✓',
168	        ThreadSyncStatus.nothingToDo => 'No Thread network configured yet',
169	        ThreadSyncStatus.unreachable => "Couldn't reach the hub — try again",
170	      };
171	      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(message)));
172	      if (result.status == ThreadSyncStatus.adopted) _loadActiveDataset();
173	    } finally {
174	      if (mounted) setState(() => _syncingThread = false);
175	    }
176	  }
