9	/// Shows the [AddControllerSheet] (QR scan or manual PSK entry), saves the
10	/// resulting PSK, and reconnects [HubConnection] — the shared "add a hub"
11	/// flow used by both the home screen FAB and the Flux Hub settings screen.
12	///
13	/// The controller ID always comes from the QR code's `id=` field — never
14	/// from whatever hub happens to already be connected, since that would
15	/// silently mis-associate a new PSK with the wrong controller. The manual
16	/// hex-only PSK entry has no ID of its own, so it only works when
17	/// [knownControllerId] is supplied: the Settings screen passes the hostname
18	/// of the (already-discovered-but-unpaired) controller it's currently
19	/// displaying as a "re-enter the PSK for the box I'm looking at" hint. The
20	/// home screen FAB (adding a hub for the first time) passes nothing, so
21	/// manual entry there requires the QR's `id=` and correctly fails otherwise.
22	///
23	/// Shows its own snackbar feedback on failure/success. Returns true once a
24	/// controller was found and connected.
25	Future<bool> runAddControllerFlow(BuildContext context, {String? knownControllerId}) async {
26	  final result = await showModalBottomSheet<String>(
27	    context:            context,
28	    isScrollControlled: true,
29	    backgroundColor:    Colors.transparent,
30	    builder: (_) => const AddControllerSheet(),
31	  );
32	  if (result == null || !context.mounted) return false;
33	
34	  // Parse flux://setup?id=<controllerId>&psk=<hex32>  OR  raw hex
35	  Uint8List? psk;
36	  String?    controllerId;
37	  if (result.startsWith('flux://setup')) {
38	    final uri = Uri.tryParse(result);
39	    psk          = _hexToBytes(uri?.queryParameters['psk'] ?? '');
40	    controllerId = uri?.queryParameters['id'];
41	  } else {
42	    psk = _hexToBytes(result.trim());
43	  }
44	
45	  if (psk == null) {
46	    if (context.mounted) {
47	      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
48	          content: Text('Invalid PSK — expected 32 hex characters')));
49	    }
50	    return false;
51	  }
52	
53	  controllerId ??= knownControllerId;
54	
55	  if (controllerId == null || controllerId.isEmpty) {
56	    if (context.mounted) {
57	      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
58	          content: Text('Could not determine controller ID — scan the QR code')));
59	    }
60	    return false;
61	  }
62	
63	  await ControllerSettings.savePsk(controllerId, psk, dtlsIdentity: controllerId);
64	
65	  final hub = context.read<HubConnection>();
66	  // Reflect "hub configured" immediately so the UI stops showing "NO HUB YET"
67	  // even if the controller can't be reached right now.
68	  await hub.refreshConfiguredState();
69	  final found = await hub.reconnect();
70	  if (context.mounted) {
