6	// ─────────────────────────────────────────────────────────────────────────────
7	// EnergyHistoryRecorder
8	//
9	// Consumes periodic one-shot reads of CumulativeEnergyImported (mWh) and
10	// computes per-15-min consumption as the delta between consecutive readings.
11	//
12	// Why reads instead of subscription:
13	//   The Matter device only pushes ActivePower (EPM 0x90) via the subscription
14	//   stream.  CumulativeEnergyImported (EEM 0x91) is available only via direct
15	//   attribute reads.  DeviceProvider polls it every second.
16	//
17	// Sealing strategy — cumulative delta:
18	//   _bucketStartMwh  = device reading at the start of the current 15-min slot.
19	//   On each new reading in the same slot: update _latestMwh only.
20	//   On the first reading of a NEW slot: seal = latestMwh − bucketStartMwh.
21	//   One disk write per 15 minutes.
22	//
23	// Live odometer:
24	//   Returns the latest known cumulative reading directly — no estimation.
25	//
26	// Retention: 7 days, pruned on each seal.
27	// ─────────────────────────────────────────────────────────────────────────────
28	
29	class EnergyHistoryRecorder {
30	  EnergyHistoryRecorder({
31	    required String          deviceId,
32	    required DeviceStore     store,
33	    required void Function() onUpdated,
34	    DateTime Function()      now = DateTime.now,
35	  })  : _deviceId  = deviceId,
36	        _store     = store,
37	        _onUpdated = onUpdated,
38	        _now       = now {
39	    _history = store.loadEnergyHistory(deviceId);
40	  }
41	
42	  static const _kRetention = Duration(days: 7);
43	
44	  final String          _deviceId;
45	  final DeviceStore     _store;
46	  final void Function() _onUpdated;
47	  final DateTime Function() _now;
48	
49	  List<EnergyBucket> _history = [];
50	
51	  // ── Bucket state ──────────────────────────────────────────────────────────
52	  DateTime? _openBucketStart;
53	  int?      _bucketStartMwh;          // imported baseline for open bucket
54	  int?      _latestMwh;               // latest imported cumulative
55	  int?      _exportedBucketStartMwh;  // exported baseline for open bucket
56	  int?      _latestExportedMwh;       // latest exported cumulative
57	
58	  // ── Public API ─────────────────────────────────────────────────────────────
59	
60	  /// Immutable view of sealed buckets, oldest first.
61	  List<EnergyBucket> get history => List.unmodifiable(_history);
62	
63	  /// Energy accumulated in the current (unsealed) 15-min bucket, in Wh.
64	  int get currentBucketWh {
65	    if (_bucketStartMwh == null || _latestMwh == null) return 0;
66	    return ((_latestMwh! - _bucketStartMwh!).clamp(0, 999999999) / 1000).round();
67	  }
68	
69	  /// Exported energy accumulated in the current (unsealed) 15-min bucket, Wh.
70	  int get currentExportedBucketWh {
71	    if (_exportedBucketStartMwh == null || _latestExportedMwh == null) return 0;
72	    return ((_latestExportedMwh! - _exportedBucketStartMwh!).clamp(0, 999999999) / 1000).round();
73	  }
74	
75	  /// Called on every cumulative-energy update from the device.
76	  /// [exportedMwh] is null if the device doesn't report exported energy.
77	  void record(DateTime now, int importedMwh, {int? exportedMwh}) {
78	    _latestMwh = importedMwh;
79	    if (exportedMwh != null) _latestExportedMwh = exportedMwh;
80	
81	    final bucketStart = _floorToBucket(now);
82	
83	    if (_openBucketStart == null) {
84	      _openBucketStart        = bucketStart;
85	      _bucketStartMwh         = importedMwh;
86	      _exportedBucketStartMwh = exportedMwh;
87	      _onUpdated();
88	      return;
89	    }
90	
91	    if (bucketStart == _openBucketStart) {
92	      _onUpdated();
93	      return;
94	    }
95	
96	    // ── New slot: seal the previous bucket ────────────────────────────────────
97	    final deltaImportedMwh = importedMwh - _bucketStartMwh!;
98	    final sealedImportedWh = (deltaImportedMwh / 1000.0).round()
99	        .clamp(0, deltaImportedMwh ~/ 1000 + 1);
100	
101	    int sealedExportedWh = 0;
102	    if (_exportedBucketStartMwh != null && _latestExportedMwh != null) {
103	      final deltaExportedMwh = _latestExportedMwh! - _exportedBucketStartMwh!;
104	      sealedExportedWh = (deltaExportedMwh / 1000.0).round()
105	          .clamp(0, deltaExportedMwh ~/ 1000 + 1);
106	    }
107	
108	    _history.add(EnergyBucket(
109	      time:       _openBucketStart!,
110	      wh:         sealedImportedWh,
111	      exportedWh: sealedExportedWh,
112	    ));
113	    _prune();
114	    unawaited(_store.saveEnergyHistory(_deviceId, _history));
115	
116	    _openBucketStart        = bucketStart;
117	    _bucketStartMwh         = importedMwh;
118	    _exportedBucketStartMwh = exportedMwh ?? _exportedBucketStartMwh;
119	    _onUpdated();
120	  }
121	
122	  // ── Private ────────────────────────────────────────────────────────────────
123	
124	  static DateTime _floorToBucket(DateTime dt) {
125	    final m = (dt.minute ~/ 15) * 15;
126	    return DateTime(dt.year, dt.month, dt.day, dt.hour, m);
127	  }
128	
129	  void _prune() {
130	    final cutoff = _now().subtract(_kRetention);
131	    _history.removeWhere((b) => b.time.isBefore(cutoff));
132	  }
133	}
