// Flow connectors — a dim rail with a moving dot whose speed ∝ power.
// A single shared "seconds" clock drives every line; pos wraps continuously.
// ─────────────────────────────────────────────────────────────────────────────

class _HFlow extends StatelessWidget {
  const _HFlow({
    required this.clock,
    required this.watts,
    required this.forward,
    required this.color,
  });

  final Animation<double> clock;
  final double watts;
  final bool   forward;
  final Color  color;

  @override
  Widget build(BuildContext context) => SizedBox(
        height: 72,
        child: AnimatedBuilder(
          animation: clock,
          builder: (_, __) => CustomPaint(
            painter: _FlowPainter(
              seconds: clock.value,
              watts:   watts,
              forward: forward,
              color:   color,
              horizontal: true,
            ),
            size: Size.infinite,
          ),
        ),
      );
}

class _VFlow extends StatelessWidget {
  const _VFlow({
    required this.clock,
    required this.watts,
    required this.downward,
    required this.color,
  });

  final Animation<double> clock;
  final double watts;
  final bool   downward;
  final Color  color;

  @override
  Widget build(BuildContext context) => SizedBox(
        height: 26,
        child: AnimatedBuilder(
          animation: clock,
          builder: (_, __) => CustomPaint(
            painter: _FlowPainter(
              seconds: clock.value,
              watts:   watts,
              forward: downward,
              color:   color,
              horizontal: false,
            ),
            size: Size.infinite,
          ),
        ),
      );
}

class _FlowPainter extends CustomPainter {
  const _FlowPainter({
    required this.seconds,
    required this.watts,
    required this.forward,
    required this.color,
    required this.horizontal,
  });

  final double seconds;
  final double watts;
  final bool   forward;
  final Color  color;
  final bool   horizontal;

  @override
  void paint(Canvas canvas, Size size) {
    final cx = size.width / 2;
    final cy = size.height / 2;

    final Offset a, b;
    if (horizontal) {
      a = Offset(0, cy);
      b = Offset(size.width, cy);
    } else {
      a = Offset(cx, 0);
      b = Offset(cx, size.height);
    }

    // Dim rail — always visible.
    canvas.drawLine(
      a, b,
      Paint()
        ..color = color.withAlpha(40)
        ..strokeWidth = 2,
    );

    if (watts < 1) return; // effectively idle — no moving dot

    // Crossings per second scales with power (0.15 … 2.5 Hz), capped.
    final speed = (watts / 2500).clamp(0.15, 2.5);
    final t = (seconds * speed) % 1.0;
    final frac = forward ? t : 1.0 - t;

    final dot = Offset.lerp(a, b, frac)!;
    final glow = (watts / 3000).clamp(0.25, 1.0);
    canvas.drawCircle(
      dot, 3.5,
      Paint()
        ..color = color.withAlpha((glow * 255).round())
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 1.5),
    );
    canvas.drawCircle(dot, 2.5, Paint()..color = color);
  }

  @override
  bool shouldRepaint(_FlowPainter old) =>
      old.seconds != seconds ||
      old.watts   != watts ||
      old.forward != forward ||
      old.color   != color;
}

