import 'package:flutter/painting.dart' show Offset;
import 'package:matter_home/models/energy_role.dart';

/// Aspect ratio of the house illustration (all SVGs share this viewBox).
const double kSceneAspect = 400 / 300;

/// The fixed asset "slots" in the home illustration. Each maps to an
/// [EnergyRole] (except [home], the load hub) and carries its overlay SVG plus
/// a normalized [0..1] anchor used to place badges and route flow paths over
/// the rendered scene. Anchors are hand-tuned to the art in `assets/energy/`.
enum SceneAsset {
  grid,
  pv,
  battery,
  carCharger,
  heatPump,
  home;

  /// The energy role this slot represents, or null for the house itself.
  EnergyRole? get role => switch (this) {
        SceneAsset.grid       => EnergyRole.grid,
        SceneAsset.pv         => EnergyRole.pv,
        SceneAsset.battery    => EnergyRole.homeBattery,
        SceneAsset.carCharger => EnergyRole.carCharger,
        SceneAsset.heatPump   => EnergyRole.heatPump,
        SceneAsset.home       => null,
      };

  /// Overlay SVG drawn on top of the base scene (null for [home]).
  String? get svg => switch (this) {
        SceneAsset.grid       => 'assets/energy/grid.svg',
        SceneAsset.pv         => 'assets/energy/pv.svg',
        SceneAsset.battery    => 'assets/energy/battery.svg',
        SceneAsset.carCharger => 'assets/energy/charger.svg',
        SceneAsset.heatPump   => 'assets/energy/heatpump.svg',
        SceneAsset.home       => null,
      };

  /// Normalized anchor over the scene (x,y in [0..1]).
  Offset get anchor => switch (this) {
        SceneAsset.grid       => const Offset(0.11, 0.40),
        SceneAsset.pv         => const Offset(0.45, 0.40),
        SceneAsset.battery    => const Offset(0.29, 0.64),
        SceneAsset.carCharger => const Offset(0.82, 0.64),
        SceneAsset.heatPump   => const Offset(0.75, 0.70),
        SceneAsset.home       => const Offset(0.50, 0.60),
      };

  /// Assets that carry an overlay + can flow to/from the house, in draw order.
  static const overlays = [grid, pv, battery, heatPump, carCharger];
}

import 'package:flutter/material.dart';
import 'package:flutter_svg/flutter_svg.dart';
import 'package:go_router/go_router.dart';
import 'package:matter_home/models/device_view.dart';
import 'package:matter_home/models/energy_role.dart';
import 'package:matter_home/models/energy_scene.dart';
import 'package:matter_home/models/energy_summary.dart';
import 'package:matter_home/providers/device_provider.dart';
import 'package:matter_home/utils/power_format.dart';
import 'package:provider/provider.dart';

// Per-asset accent colours (match the schematic the scene replaces).
const _pvColor      = Color(0xFFF5A623);
const _gridImport   = Color(0xFFE05353);
const _gridExport   = Color(0xFF4CAF50);
const _batteryColor = Color(0xFF3DBFA0);
const _carColor     = Color(0xFF8E7CFF);
const _heatColor    = Color(0xFF4FC3E8);

/// Illustrated home with each energy asset (roof PV, driveway charger, garage
/// battery, heat pump, grid pole) drawn in its slot, overlaid with live-data
/// badges and animated energy-flow particles. Replaces the schematic
/// `HomeEnergyOverview` in the Energy category view.
class HouseEnergyScene extends StatefulWidget {
  const HouseEnergyScene({super.key});

  @override
  State<HouseEnergyScene> createState() => _HouseEnergySceneState();
}

class _HouseEnergySceneState extends State<HouseEnergyScene>
    with SingleTickerProviderStateMixin {
  // Continuously-increasing "seconds" clock; each flow advances its particle at
  // its own power-proportional speed without wrap-around jumps.
  late final AnimationController _clock;

  @override
  void initState() {
    super.initState();
    _clock = AnimationController.unbounded(vsync: this)
      ..animateTo(1e6, duration: const Duration(seconds: 1000000));
  }

  @override
  void dispose() {
    _clock.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final provider = context.watch<DeviceProvider>();
    final s        = provider.energySummary;
    final cs       = Theme.of(context).colorScheme;
    final vms      = _viewModels(s, cs);
    final flows    = [
      for (final vm in vms)
        if (vm.asset != SceneAsset.home && vm.configured && vm.watts >= 1)
          _Flow(
            start:   vm.asset.anchor,
            end:     SceneAsset.home.anchor,
            color:   vm.color,
            watts:   vm.watts,
            forward: vm.toHome,
          ),
    ];

    return Card(
      margin: const EdgeInsets.fromLTRB(16, 16, 16, 4),
      clipBehavior: Clip.antiAlias,
      child: Padding(
        padding: const EdgeInsets.all(8),
        child: AspectRatio(
          aspectRatio: kSceneAspect,
          child: Stack(
            fit: StackFit.expand,
            children: [
              // Base illustration
              SvgPicture.asset('assets/energy/scene.svg', fit: BoxFit.contain),

              // Asset overlays (dimmed when no device is assigned)
              for (final vm in vms)
                if (vm.asset.svg != null)
                  Opacity(
                    opacity: vm.configured ? 1 : 0.22,
                    child: SvgPicture.asset(vm.asset.svg!, fit: BoxFit.contain),
                  ),

              // Animated energy-flow particles
              AnimatedBuilder(
                animation: _clock,
                builder: (_, __) => CustomPaint(
                  painter: _SceneFlowPainter(seconds: _clock.value, flows: flows),
                ),
              ),

              // Header
              Positioned(
                left: 10, top: 8,
                child: Row(
                  children: [
                    Icon(Icons.home_outlined, size: 14, color: cs.onSurfaceVariant),
                    const SizedBox(width: 5),
                    Text('HOME ENERGY',
                        style: TextStyle(
                            fontSize: 10,
                            fontWeight: FontWeight.w700,
                            letterSpacing: 1.1,
                            color: cs.onSurfaceVariant)),
                  ],
                ),
              ),

              // Live badges + tap targets
              for (final vm in vms)
                Align(
                  alignment: Alignment(
                    vm.asset.anchor.dx * 2 - 1,
                    vm.asset.anchor.dy * 2 - 1,
                  ),
                  child: _Badge(
                    vm: vm,
                    onTap: () => _onTapAsset(context, provider, vm),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }

  List<_AssetVM> _viewModels(EnergySummary s, ColorScheme cs) {
    final gridExporting = s.gridExport > s.gridImport;
    return [
      _AssetVM(
        asset: SceneAsset.grid,
        configured: s.hasGrid,
        watts: gridExporting ? s.gridExport : s.gridImport,
        toHome: !gridExporting, // import flows to the house
        color: gridExporting ? _gridExport : _gridImport,
        caption: gridExporting ? 'exporting' : 'importing',
      ),
      _AssetVM(
        asset: SceneAsset.pv,
        configured: s.hasPv,
        watts: s.pvProduction,
        toHome: true,
        color: _pvColor,
      ),
      _AssetVM(
        asset: SceneAsset.battery,
        configured: s.hasBattery,
        watts: s.batteryDischarge > s.batteryCharge
            ? s.batteryDischarge
            : s.batteryCharge,
        toHome: s.batteryDischarge >= s.batteryCharge, // discharge feeds house
        color: _batteryColor,
        caption: s.batterySocPercent != null ? '${s.batterySocPercent}%' : null,
      ),
      _AssetVM(
        asset: SceneAsset.heatPump,
        configured: s.hasHeatPump,
        watts: s.heatPump,
        toHome: false, // house powers the heat pump
        color: _heatColor,
      ),
      _AssetVM(
        asset: SceneAsset.carCharger,
        configured: s.hasCar,
        watts: s.carCharging,
        toHome: false, // house powers the car
        color: _carColor,
      ),
      _AssetVM(
        asset: SceneAsset.home,
        configured: true,
        watts: s.houseLoad.abs(),
        toHome: false,
        color: cs.primary,
      ),
    ];
  }

  Future<void> _onTapAsset(
      BuildContext context, DeviceProvider provider, _AssetVM vm) async {
    final role = vm.asset.role;
    if (role == null) return; // the house itself
    final devices =
        provider.deviceViews.where((v) => v.energyRole == role).toList();

    if (devices.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text('Assign a device to the ${role.label} slot from its '
            'settings to see it here.'),
      ));
      return;
    }
    if (devices.length == 1) {
      unawaited(context.push('/device/${devices.first.id}'));
      return;
    }
    await showModalBottomSheet<void>(
      context: context,
      builder: (sheet) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            for (final d in devices)
              ListTile(
                leading: Icon(role.icon),
                title: Text(d.name),
                onTap: () {
                  Navigator.pop(sheet);
                  unawaited(context.push('/device/${d.id}'));
                },
              ),
          ],
        ),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────

class _AssetVM {
  const _AssetVM({
    required this.asset,
    required this.configured,
    required this.watts,
    required this.toHome,
    required this.color,
    this.caption,
  });

  final SceneAsset asset;
  final bool       configured;
  final double     watts;
  final bool       toHome;
  final Color      color;
  final String?    caption;
}

// ─────────────────────────────────────────────────────────────────────────────
// Badge — a small pill anchored over an asset.
// ─────────────────────────────────────────────────────────────────────────────

class _Badge extends StatelessWidget {
  const _Badge({required this.vm, required this.onTap});
  final _AssetVM vm;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final (val, unit) = formatPowerW(vm.watts);
    final label = vm.configured ? '$val $unit' : 'Assign';
    final color = vm.configured ? vm.color : cs.onSurfaceVariant;

    return GestureDetector(
      onTap: onTap,
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
        decoration: BoxDecoration(
          color: Colors.black.withAlpha(180),
          borderRadius: BorderRadius.circular(20),
          border: Border.all(color: color.withAlpha(vm.configured ? 200 : 90)),
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              label,
              style: TextStyle(
                color: vm.configured ? Colors.white : color,
                fontSize: 11.5,
                fontWeight: FontWeight.w700,
              ),
            ),
            if (vm.caption != null && vm.configured)
              Text(vm.caption!,
                  style: TextStyle(color: color, fontSize: 8.5, height: 1.1)),
          ],
        ),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Flow painter — dim rail + a calm particle per flow, curved anchor→home.
// ─────────────────────────────────────────────────────────────────────────────

class _Flow {
  const _Flow({
    required this.start,
    required this.end,
    required this.color,
    required this.watts,
    required this.forward,
  });
  final Offset start;   // normalized
  final Offset end;     // normalized (home)
  final Color  color;
  final double watts;
  final bool   forward; // particle travels start→end when true
}

class _SceneFlowPainter extends CustomPainter {
  const _SceneFlowPainter({required this.seconds, required this.flows});
  final double seconds;
  final List<_Flow> flows;

  @override
  void paint(Canvas canvas, Size size) {
    for (final f in flows) {
      final a = Offset(f.start.dx * size.width, f.start.dy * size.height);
      final b = Offset(f.end.dx * size.width, f.end.dy * size.height);
      final mid = (a + b) / 2;
      // Gentle bow toward the top of the scene.
      final ctrl = Offset(mid.dx, mid.dy - (b - a).distance * 0.14);

      final path = Path()
        ..moveTo(a.dx, a.dy)
        ..quadraticBezierTo(ctrl.dx, ctrl.dy, b.dx, b.dy);

      canvas.drawPath(
        path,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.5
          ..color = f.color.withAlpha(46),
      );

      if (f.watts < 1) continue;
      final metric = path.computeMetrics().first;
      final speed = (0.2 + f.watts / 12000).clamp(0.2, 0.6);
      final t = (seconds * speed) % 1.0;
      final frac = f.forward ? t : 1.0 - t;
      final pos = metric.getTangentForOffset(metric.length * frac)?.position;
      if (pos == null) continue;

      canvas.drawCircle(pos, 3.2, Paint()..color = f.color);
    }
  }

  @override
  bool shouldRepaint(_SceneFlowPainter old) =>
      old.seconds != seconds || old.flows != flows;
}

