import 'package:flutter/material.dart';
import 'package:matter_home/models/energy_role.dart';

/// Aspect ratio of the isometric house illustration (`assets/energy/scene.svg`).
const double kSceneAspect = 400 / 360;

/// The energy assets surfaced on the isometric home scene. Each floats as a
/// neon "pin" (icon + live data) above the house on a stem that lands on the
/// asset's spot; [home] is the central load hub. Positions are normalized
/// [0..1] over the scene and hand-tuned to the art.
enum SceneAsset {
  grid,
  battery,
  pv,
  heatPump,
  carCharger,
  home;

  EnergyRole? get role => switch (this) {
        SceneAsset.grid       => EnergyRole.grid,
        SceneAsset.pv         => EnergyRole.pv,
        SceneAsset.battery    => EnergyRole.homeBattery,
        SceneAsset.carCharger => EnergyRole.carCharger,
        SceneAsset.heatPump   => EnergyRole.heatPump,
        SceneAsset.home       => null,
      };

  IconData get icon => role?.icon ?? Icons.home_rounded;

  /// Floating pin position (circle centre).
  Offset get pin => switch (this) {
        SceneAsset.grid       => const Offset(0.11, 0.24),
        SceneAsset.battery    => const Offset(0.29, 0.13),
        SceneAsset.pv         => const Offset(0.51, 0.08),
        SceneAsset.heatPump   => const Offset(0.72, 0.13),
        SceneAsset.carCharger => const Offset(0.90, 0.24),
        SceneAsset.home       => const Offset(0.44, 0.60),
      };

  /// Where the pin's stem lands on the house.
  Offset get stemTarget => switch (this) {
        SceneAsset.grid       => const Offset(0.16, 0.52),
        SceneAsset.battery    => const Offset(0.30, 0.58),
        SceneAsset.pv         => const Offset(0.56, 0.51),
        SceneAsset.heatPump   => const Offset(0.73, 0.56),
        SceneAsset.carCharger => const Offset(0.80, 0.64),
        SceneAsset.home       => const Offset(0.44, 0.60),
      };

  /// Assets drawn as pins with stems, in left-to-right order.
  static const pins = [grid, battery, pv, heatPump, carCharger];
}

import 'dart:async' show unawaited;

import 'package:flutter/material.dart';
import 'package:flutter_svg/flutter_svg.dart';
import 'package:go_router/go_router.dart';
import 'package:matter_home/models/energy_scene.dart';
import 'package:matter_home/models/energy_summary.dart';
import 'package:matter_home/providers/device_provider.dart';
import 'package:matter_home/utils/power_format.dart';
import 'package:provider/provider.dart';

// Neon per-asset accents.
const _pvColor      = Color(0xFFFFB13A);
const _gridImport   = Color(0xFFFF5470);
const _gridExport   = Color(0xFF3DE0A0);
const _batteryColor = Color(0xFF37E0C0);
const _carColor     = Color(0xFFB07CFF);
const _heatColor    = Color(0xFF4FD0F0);
const _homeColor    = Color(0xFFFF4FC0);
const _sceneBg      = Color(0xFF0C0722);

/// Isometric neon home with each energy asset shown as a floating pin (icon +
/// live data on a stem) above the house, plus animated energy-flow particles.
/// Replaces the schematic overview in the Energy category view.
class HouseEnergyScene extends StatefulWidget {
  const HouseEnergyScene({super.key});

  @override
  State<HouseEnergyScene> createState() => _HouseEnergySceneState();
}

class _HouseEnergySceneState extends State<HouseEnergyScene>
    with SingleTickerProviderStateMixin {
  late final AnimationController _clock;

  @override
  void initState() {
    super.initState();
    _clock = AnimationController.unbounded(vsync: this)
      ..animateTo(1e6, duration: const Duration(seconds: 1000000));
  }

  @override
  void dispose() {
    _clock.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final provider = context.watch<DeviceProvider>();
    final s        = provider.energySummary;
    final vms      = _viewModels(s);

    return Card(
      margin: const EdgeInsets.fromLTRB(16, 16, 16, 4),
      color: _sceneBg,
      clipBehavior: Clip.antiAlias,
      child: AspectRatio(
        aspectRatio: kSceneAspect,
        child: Stack(
          fit: StackFit.expand,
          children: [
            SvgPicture.asset('assets/energy/scene.svg', fit: BoxFit.cover),

            // Stems + animated flow particles
            AnimatedBuilder(
              animation: _clock,
              builder: (_, __) => CustomPaint(
                painter: _StemPainter(seconds: _clock.value, vms: vms),
              ),
            ),

            // Floating pins + central home badge
            for (final vm in vms)
              Align(
                alignment: Alignment(
                  vm.asset.pin.dx * 2 - 1,
                  vm.asset.pin.dy * 2 - 1,
                ),
                child: _Pin(vm: vm, onTap: () => _onTap(context, provider, vm)),
              ),
          ],
        ),
      ),
    );
  }

  List<_AssetVM> _viewModels(EnergySummary s) {
    final gridExporting = s.gridExport > s.gridImport;
    return [
      _AssetVM(SceneAsset.grid, s.hasGrid,
          gridExporting ? s.gridExport : s.gridImport, !gridExporting,
          gridExporting ? _gridExport : _gridImport,
          gridExporting ? 'export' : 'import'),
      _AssetVM(SceneAsset.battery, s.hasBattery,
          s.batteryDischarge > s.batteryCharge ? s.batteryDischarge : s.batteryCharge,
          s.batteryDischarge >= s.batteryCharge, _batteryColor,
          s.batterySocPercent != null ? '${s.batterySocPercent}%' : 'Battery'),
      _AssetVM(SceneAsset.pv, s.hasPv, s.pvProduction, true, _pvColor, 'Solar'),
      _AssetVM(SceneAsset.heatPump, s.hasHeatPump, s.heatPump, false, _heatColor,
          'Heat pump'),
      _AssetVM(SceneAsset.carCharger, s.hasCar, s.carCharging, false, _carColor,
          'Car'),
      _AssetVM(SceneAsset.home, true, s.houseLoad.abs(), false, _homeColor,
          'Home'),
    ];
  }

  Future<void> _onTap(
      BuildContext context, DeviceProvider provider, _AssetVM vm) async {
    final role = vm.asset.role;
    if (role == null) return;
    final devices =
        provider.deviceViews.where((v) => v.energyRole == role).toList();
    if (devices.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text('Assign a device to the ${role.label} slot from its '
            'settings to see it here.'),
      ));
      return;
    }
    if (devices.length == 1) {
      unawaited(context.push('/device/${devices.first.id}'));
      return;
    }
    await showModalBottomSheet<void>(
      context: context,
      builder: (sheet) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            for (final d in devices)
              ListTile(
                leading: Icon(role.icon),
                title: Text(d.name),
                onTap: () {
                  Navigator.pop(sheet);
                  unawaited(context.push('/device/${d.id}'));
                },
              ),
          ],
        ),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────

class _AssetVM {
  const _AssetVM(this.asset, this.configured, this.watts, this.toHome,
      this.color, this.caption);
  final SceneAsset asset;
  final bool       configured;
  final double     watts;
  final bool       toHome;
  final Color      color;
  final String     caption;
}

// ─────────────────────────────────────────────────────────────────────────────
// Neon pin — glowing circle + icon, live value + label beneath.
// ─────────────────────────────────────────────────────────────────────────────

class _Pin extends StatelessWidget {
  const _Pin({required this.vm, required this.onTap});
  final _AssetVM vm;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    final color = vm.color;
    final (val, unit) = formatPowerW(vm.watts);
    final isHome = vm.asset == SceneAsset.home;
    final dim = !vm.configured && !isHome;

    return Opacity(
      opacity: dim ? 0.5 : 1,
      child: GestureDetector(
        onTap: onTap,
        behavior: HitTestBehavior.opaque,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Container(
              width: isHome ? 46 : 40,
              height: isHome ? 46 : 40,
              decoration: BoxDecoration(
                color: _sceneBg,
                shape: BoxShape.circle,
                border: Border.all(color: color, width: 2),
                boxShadow: [
                  BoxShadow(color: color.withAlpha(dim ? 30 : 130), blurRadius: 12),
                ],
              ),
              child: Icon(vm.asset.icon, color: color, size: isHome ? 24 : 20),
            ),
            const SizedBox(height: 3),
            Text(
              vm.configured || isHome ? '$val $unit' : 'Assign',
              style: TextStyle(
                color: Colors.white,
                fontSize: 11,
                fontWeight: FontWeight.w700,
                shadows: const [Shadow(color: Colors.black, blurRadius: 3)],
              ),
            ),
            Text(
              vm.caption,
              style: TextStyle(
                color: color,
                fontSize: 8,
                height: 1.1,
                shadows: const [Shadow(color: Colors.black, blurRadius: 3)],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Stems + flow particles — a neon line from each pin down to its spot on the
// house, with a calm particle whose direction follows the energy flow.
// ─────────────────────────────────────────────────────────────────────────────

class _StemPainter extends CustomPainter {
  const _StemPainter({required this.seconds, required this.vms});
  final double seconds;
  final List<_AssetVM> vms;

  @override
  void paint(Canvas canvas, Size size) {
    for (final vm in vms) {
      if (vm.asset == SceneAsset.home) continue;
      final a = Offset(vm.asset.pin.dx * size.width,
          vm.asset.pin.dy * size.height + 24); // just below the circle
      final b = Offset(vm.asset.stemTarget.dx * size.width,
          vm.asset.stemTarget.dy * size.height);

      canvas.drawLine(
        a, b,
        Paint()
          ..strokeWidth = 1.3
          ..color = vm.color.withAlpha(vm.configured ? 90 : 30),
      );

      if (!vm.configured || vm.watts < 1) continue;
      final speed = (0.2 + vm.watts / 12000).clamp(0.2, 0.6);
      final t = (seconds * speed) % 1.0;
      final frac = vm.toHome ? t : 1.0 - t; // pin→house when energy enters home
      final pos = Offset.lerp(a, b, frac)!;
      canvas.drawCircle(pos, 3, Paint()..color = vm.color);
      canvas.drawCircle(
          pos, 5, Paint()..color = vm.color.withAlpha(80));
    }
  }

  @override
  bool shouldRepaint(_StemPainter old) =>
      old.seconds != seconds || old.vms != vms;
}

import 'package:flutter/material.dart';
import 'package:matter_home/models/energy_role.dart';

/// Aspect ratio of the house artwork (`assets/energy/house.png`, 1023×909).
const double kSceneAspect = 1023 / 909;

/// Energy assets shown on the illustrated home photo. Each configured asset
/// gets a pastel value badge positioned over its spot in the picture; [home]
/// is the whole-house total. Positions are normalized [0..1] over the image
/// and hand-tuned to the artwork.
enum SceneAsset {
  grid,
  pv,
  battery,
  heatPump,
  carCharger,
  home;

  EnergyRole? get role => switch (this) {
        SceneAsset.grid       => EnergyRole.grid,
        SceneAsset.pv         => EnergyRole.pv,
        SceneAsset.battery    => EnergyRole.homeBattery,
        SceneAsset.carCharger => EnergyRole.carCharger,
        SceneAsset.heatPump   => EnergyRole.heatPump,
        SceneAsset.home       => null,
      };

  IconData get icon => role?.icon ?? Icons.home_rounded;

  /// Badge position over the artwork.
  Offset get anchor => switch (this) {
        SceneAsset.grid       => const Offset(0.42, 0.40),
        SceneAsset.pv         => const Offset(0.40, 0.13),
        SceneAsset.battery    => const Offset(0.37, 0.70),
        SceneAsset.heatPump   => const Offset(0.16, 0.64),
        SceneAsset.carCharger => const Offset(0.72, 0.58),
        SceneAsset.home       => const Offset(0.80, 0.22),
      };

  static const all = [grid, pv, battery, heatPump, carCharger, home];
}

import 'package:flutter/material.dart';
import 'package:matter_home/models/energy_scene.dart';
import 'package:matter_home/models/energy_summary.dart';
import 'package:matter_home/providers/device_provider.dart';
import 'package:matter_home/utils/power_format.dart';
import 'package:provider/provider.dart';

// Soft pastel accents per asset.
const _pvColor      = Color(0xFFF6D08A); // amber
const _gridImport   = Color(0xFFF2A9A0); // coral
const _gridExport   = Color(0xFFA9E0C0); // mint
const _batteryColor = Color(0xFFA9E0C0); // mint
const _carColor     = Color(0xFFCDBBEF); // lavender
const _heatColor    = Color(0xFFA9D8EE); // sky
const _homeColor    = Color(0xFFF3B8D6); // pink
const _badgeInk     = Color(0xFF2A2540); // dark text on pastel

/// The illustrated home (transparent-background photo) with a pastel value
/// badge over each **assigned** energy asset showing its current power. Purely
/// informational — no flow animation, no tap targets.
class HouseEnergyScene extends StatelessWidget {
  const HouseEnergyScene({super.key});

  @override
  Widget build(BuildContext context) {
    final s = context.watch<DeviceProvider>().energySummary;

    return Padding(
      padding: const EdgeInsets.fromLTRB(12, 12, 12, 4),
      child: AspectRatio(
        aspectRatio: kSceneAspect,
        child: Stack(
          fit: StackFit.expand,
          children: [
            Image.asset('assets/energy/house.png', fit: BoxFit.contain),
            for (final b in _badges(s))
              Align(
                alignment: Alignment(b.at.dx * 2 - 1, b.at.dy * 2 - 1),
                child: _Badge(icon: b.icon, label: b.label, color: b.color),
              ),
          ],
        ),
      ),
    );
  }

  List<_BadgeData> _badges(EnergySummary s) {
    final out = <_BadgeData>[];
    void add(SceneAsset a, bool configured, double watts, Color color) {
      if (!configured) return;
      final (val, unit) = formatPowerW(watts);
      out.add(_BadgeData(a.anchor, a.icon, '$val $unit', color));
    }

    final exporting = s.gridExport > s.gridImport;
    add(SceneAsset.grid, s.hasGrid, exporting ? s.gridExport : s.gridImport,
        exporting ? _gridExport : _gridImport);
    add(SceneAsset.pv, s.hasPv, s.pvProduction, _pvColor);
    add(SceneAsset.battery, s.hasBattery,
        s.batteryDischarge > s.batteryCharge ? s.batteryDischarge : s.batteryCharge,
        _batteryColor);
    add(SceneAsset.heatPump, s.hasHeatPump, s.heatPump, _heatColor);
    add(SceneAsset.carCharger, s.hasCar, s.carCharging, _carColor);
    // Home total is always shown.
    add(SceneAsset.home, true, s.houseLoad.abs(), _homeColor);
    return out;
  }
}

class _BadgeData {
  const _BadgeData(this.at, this.icon, this.label, this.color);
  final Offset at;
  final IconData icon;
  final String label;
  final Color color;
}

class _Badge extends StatelessWidget {
  const _Badge({required this.icon, required this.label, required this.color});
  final IconData icon;
  final String label;
  final Color color;

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 5),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.92),
        borderRadius: BorderRadius.circular(20),
        boxShadow: const [
          BoxShadow(color: Color(0x55000000), blurRadius: 6, offset: Offset(0, 2)),
        ],
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(icon, size: 14, color: _badgeInk),
          const SizedBox(width: 5),
          Text(
            label,
            style: const TextStyle(
              color: _badgeInk,
              fontSize: 12,
              fontWeight: FontWeight.w700,
            ),
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';

/// A clean isometric wireframe house with roof solar panels. Deliberately
/// minimal — the base model for the Energy view; live-data overlays come later.
class HouseEnergyScene extends StatelessWidget {
  const HouseEnergyScene({super.key});

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    return Card(
      margin: const EdgeInsets.fromLTRB(16, 16, 16, 4),
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: AspectRatio(
          aspectRatio: 4 / 3,
          child: CustomPaint(
            painter: _WireframeHouse(color: cs.onSurface.withValues(alpha: 0.9)),
          ),
        ),
      ),
    );
  }
}

class _WireframeHouse extends CustomPainter {
  _WireframeHouse({required this.color});
  final Color color;

  // House dimensions in scene units (centred on the origin footprint).
  static const _w = 2.0; // half-width  (x)
  static const _d = 1.5; // half-depth  (y)
  static const _h = 1.3; // wall height (z)
  static const _r = 1.15; // roof rise  (z)

  @override
  void paint(Canvas canvas, Size size) {
    final unit = size.width / 11;
    final hw = unit * 0.9, hh = unit * 0.5, hz = unit * 0.95;
    final cx = size.width / 2;
    final cy = size.height * 0.46;

    // Isometric (2:1) projection.
    Offset p(double x, double y, double z) =>
        Offset(cx + (x - y) * hw, cy + (x + y) * hh - z * hz);

    // Corners: base (z=0), wall-top (z=h), ridge (z=h+r, along x at y=0).
    final b = p(_w, -_d, 0),  c = p(_w, _d, 0),  dd = p(-_w, _d, 0);
    final a2 = p(-_w, -_d, _h), b2 = p(_w, -_d, _h),
          c2 = p(_w, _d, _h),   d2 = p(-_w, _d, _h);
    final rL = p(-_w, 0, _h + _r), rR = p(_w, 0, _h + _r);

    final stroke = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.4
      ..strokeJoin = StrokeJoin.round
      ..strokeCap = StrokeCap.round
      ..color = color;

    Path poly(List<Offset> pts) {
      final path = Path()..moveTo(pts.first.dx, pts.first.dy);
      for (final o in pts.skip(1)) {
        path.lineTo(o.dx, o.dy);
      }
      return path..close();
    }

    // Visible faces
    canvas
      ..drawPath(poly([b, c, c2, b2]), stroke)   // right wall
      ..drawPath(poly([c, dd, d2, c2]), stroke)  // front-left wall
      ..drawPath(poly([d2, c2, rR, rL]), stroke) // front roof slope
      ..drawPath(poly([b2, c2, rR]), stroke)     // right gable
      ..drawLine(rL, rR, stroke);                // ridge

    // Solar panel grid on the front roof slope (rL·rR top edge, d2·c2 eave).
    Offset onSlope(double a, double t) => Offset.lerp(
          Offset.lerp(rL, rR, a)!, // ridge edge
          Offset.lerp(d2, c2, a)!, // eave edge
          t,
        )!;

    final panel = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.1
      ..color = color;

    const a0 = 0.12, a1 = 0.88, t0 = 0.2, t1 = 0.9;
    canvas.drawPath(
      poly([onSlope(a0, t0), onSlope(a1, t0), onSlope(a1, t1), onSlope(a0, t1)]),
      panel,
    );
    for (var i = 1; i < 4; i++) {
      final a = a0 + (a1 - a0) * i / 4; // 4 columns
      canvas.drawLine(onSlope(a, t0), onSlope(a, t1), panel);
    }
    for (var i = 1; i < 3; i++) {
      final t = t0 + (t1 - t0) * i / 3; // 3 rows
      canvas.drawLine(onSlope(a0, t), onSlope(a1, t), panel);
    }
  }

  @override
  bool shouldRepaint(_WireframeHouse old) => old.color != color;
}

