// ─── Modbus devices ─────────────────────────────────────────────────────────
// The controller can also poll non-Matter devices over Modbus TCP (e.g. a PV
// inverter on the home LAN) and expose them to the app *as if they were Matter
// devices*: each is registered in the same device registry under a synthetic
// node ID (Matter-reserved range) with a real Matter device_type, and its
// readings are pushed through the same /events pipeline under the same attribute
// keys a Matter device would use.  Only the provisioning surface below is
// Modbus-specific; Device / AttrsUpdate / DeviceStateEvent are reused verbatim.

// Register-map profile that tells the controller how to decode a device.
// (SUNSPEC stays 0 for wire/NVS compatibility; UNKNOWN is discovery-only.)
enum ModbusProfile {
    MODBUS_PROFILE_SUNSPEC   = 0;  // SunSpec PV inverter
    MODBUS_PROFILE_UNKNOWN   = 1;  // responds on :502 but profile not identified
                                   // (discovery result only — not decodable)
    MODBUS_PROFILE_VM3P75CT  = 2;  // Victron VM-3P75CT 3-phase energy meter
    // more meters/inverters to come — see modbus_devices_plan.md
}

// Transport for a Modbus device. TCP is the default; some meters (e.g. the
// VM-3P75CT) speak Modbus over UDP.
enum ModbusTransport {
    MODBUS_TRANSPORT_TCP = 0;
    MODBUS_TRANSPORT_UDP = 1;
}

// POST /modbus/devices
// Add or update a Modbus TCP device.  The controller persists the config,
// registers the device (device_type per profile), and begins polling it.
message ModbusDeviceConfig {
    string        host         = 1;  // inverter IP/hostname on the controller's LAN
    uint32        port         = 2;  // Modbus TCP port; 0 = default 502
    uint32        unit_id      = 3;  // Modbus unit/slave id
    ModbusProfile profile      = 4;  // register-map profile
    uint32          poll_seconds = 5;  // poll interval; 0 = profile default
    string          name         = 6;  // display name registered for the device
    uint64          node_id      = 7;  // 0 = controller assigns a synthetic node id
    ModbusTransport transport    = 8;  // TCP (default) or UDP
}

// One candidate surfaced by a discovery scan (not yet registered).
message ModbusCandidate {
    string          host      = 1;
    ModbusProfile   profile   = 2;  // profile the scan positively identified
    string          serial    = 3;  // device serial (SunSpec Common model), if readable
    string          model     = 4;  // e.g. "SunSpec 103", or manufacturer model string
    ModbusTransport transport = 5;  // TCP or UDP (which scan found it)
}

// GET /modbus/discovered
// Result of scanning the controller's own Ethernet subnet for Modbus devices.
// Suggest-only: nothing is polled until the app confirms via POST /modbus/devices.
message ModbusDiscovered {
    repeated ModbusCandidate candidates = 1;
}

// ─── Attributes ───────────────────────────────────────────────────────────────

// A single cluster attribute with a typed value.
// Key names must match SubscriptionKeys.kt exactly.
message Attr {
    string key = 1;
    oneof value {
        bool   bool_val  = 2;
        sint32 int_val   = 3;
        sint64 long_val  = 4;
    }
}

// A batch of attribute updates for one node.
message AttrsUpdate {
    uint64        node_id = 1;
    repeated Attr attrs   = 2;
}

// ─── Events (controller → app) ───────────────────────────────────────────────

