void hnd_devices_post(coap_resource_t *resource,
                      coap_session_t  *session,
                      const coap_pdu_t *request,
                      const coap_string_t *query,
                      coap_pdu_t       *response)
{
    uint8_t *body; size_t body_len;
    if (!read_body(request, &body, &body_len)) {
        send_status(resource, session, request, response, 1, "no body");
        return;
    }
    flux_RenameDeviceRequest rr = flux_RenameDeviceRequest_init_zero;
    pb_istream_t is = pb_istream_from_buffer(body, body_len);
    if (!pb_decode(&is, flux_RenameDeviceRequest_fields, &rr) || rr.node_id == 0) {
        free(body);
        send_status(resource, session, request, response, 1, "decode failed");
        return;
    }
    free(body);
    esp_err_t err = flux_device_set_name(rr.node_id, rr.name);
    if (err == ESP_ERR_NOT_FOUND) {
        send_status(resource, session, request, response, 2, "device not found");
        return;
    }
    if (err != ESP_OK) {
        send_status(resource, session, request, response, 1, "nvs error");
        return;
    }
    ESP_LOGI(TAG, "POST /devices rename %016llx → %.63s",
             (unsigned long long)rr.node_id, rr.name);
    send_status(resource, session, request, response, 0, "ok");
}

