import 'package:flutter/foundation.dart';
import 'package:matter_home/models/energy_history.dart';
import 'package:matter_home/services/proto/flux.pb.dart' as $proto;
import 'package:matter_home/services/proto/flux.pbenum.dart' as $enum;

/// One price interval: its start time and the price in ct/kWh (may be negative —
/// day-ahead spot prices can go below zero).
@immutable
class PricePoint {
  const PricePoint({required this.time, required this.ctPerKwh});
  final DateTime time;
  final double ctPerKwh;
}

/// Decoded day-ahead price curve: per-interval ct/kWh plus the min/max/avg for
/// the covered window. Built from [$proto.PriceCurve]; the UI never sees raw
/// protobuf. Prices are the wholesale spot curve.
@immutable
class EnergyPrices {
  const EnergyPrices({
    required this.points,
    required this.resolution,
    required this.currency,
    required this.stale,
    required this.minCt,
    required this.maxCt,
    required this.avgCt,
  });

  final List<PricePoint> points;
  final Duration resolution;
  final String currency;
  final bool stale;
  final double minCt;
  final double maxCt;
  final double avgCt;

  bool get isEmpty => points.isEmpty;

  /// The interval covering [now], or null if outside coverage.
  PricePoint? currentAt(DateTime now) {
    for (final p in points) {
      if (!now.isBefore(p.time) && now.isBefore(p.time.add(resolution))) return p;
    }
    return null;
  }

  /// Total cost (in cents) of the consumed energy in [history], each bucket
  /// valued at the spot price covering its time. Null when there's no overlap
  /// between consumption and price coverage.
  double? consumptionCostCents(EnergyHistoryData? history) {
    if (history == null || history.points.isEmpty || points.isEmpty) return null;
    final bucketHours = history.bucket.inSeconds / 3600.0;
    var cents = 0.0;
    var any = false;
    for (final p in history.points) {
      final price = currentAt(p.time);
      if (price == null) continue;
      final kwh = p.consumptionW * bucketHours / 1000.0;
      cents += kwh * price.ctPerKwh;
      any = true;
    }
    return any ? cents : null;
  }

  factory EnergyPrices.fromProto($proto.PriceCurve c) {
    final res = c.resolutionSeconds == 0 ? 3600 : c.resolutionSeconds;
    final start = c.startEpoch.toInt();

    // Convert the stored unit to ct/kWh. Canonical is µEUR/kWh (÷10000);
    // EUR/MWh (informational) is ÷10.
    final divisor =
        c.unit == $enum.PriceUnit.PRICE_UNIT_EUR_PER_MWH ? 10.0 : 10000.0;
    final cts = c.prices.map((p) => p / divisor).toList(growable: false);

    final currency = c.currency.isNotEmpty ? c.currency : 'EUR';
    if (cts.isEmpty) {
      return EnergyPrices(
        points: const [],
        resolution: Duration(seconds: res),
        currency: currency,
        stale: c.stale,
        minCt: 0, maxCt: 0, avgCt: 0,
      );
    }

    final minCt = cts.reduce((a, b) => a < b ? a : b);
    final maxCt = cts.reduce((a, b) => a > b ? a : b);
    final avgCt = cts.reduce((a, b) => a + b) / cts.length;

    final points = <PricePoint>[
      for (var i = 0; i < cts.length; i++)
        PricePoint(
          time: DateTime.fromMillisecondsSinceEpoch((start + i * res) * 1000),
          ctPerKwh: cts[i],
        ),
    ];

    return EnergyPrices(
      points: points,
      resolution: Duration(seconds: res),
      currency: currency,
      stale: c.stale,
      minCt: minCt,
      maxCt: maxCt,
      avgCt: avgCt,
    );
  }
}

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:matter_home/models/energy_history.dart';
import 'package:matter_home/models/energy_prices.dart';
import 'package:matter_home/providers/device_provider.dart';
import 'package:provider/provider.dart';

const _priceColor   = Color(0xFF8FC7E8); // blue — price bars
const _consumeColor = Color(0xFFF3B8D6); // pink — consumption overlay

/// A "Prices & consumption" card: the day-ahead spot price curve as bars with a
/// readable ct/kWh axis, home consumption overlaid, and the aggregated cost of
/// consumed energy shown top-left.
class EnergyPriceCard extends StatefulWidget {
  const EnergyPriceCard({super.key});

  @override
  State<EnergyPriceCard> createState() => _EnergyPriceCardState();
}

class _EnergyPriceCardState extends State<EnergyPriceCard> {
  Timer? _refresh;
  static const _refreshInterval = Duration(seconds: 60);

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) context.read<DeviceProvider>().fetchEnergyPrices();
    });
    _refresh = Timer.periodic(_refreshInterval, (_) {
      if (mounted) context.read<DeviceProvider>().fetchEnergyPrices();
    });
  }

  @override
  void dispose() {
    _refresh?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final provider = context.watch<DeviceProvider>();
    final prices   = provider.energyPrices;
    final history  = provider.energyHistory;
    final loading  = provider.energyPricesLoading;

    return Card(
      margin: const EdgeInsets.fromLTRB(16, 4, 16, 4),
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            _header(context),
            const SizedBox(height: 12),
            if (prices == null || prices.isEmpty)
              _placeholder(context, loading)
            else ...[
              _readout(context, prices, history),
              const SizedBox(height: 10),
              _chart(prices, history),
              const SizedBox(height: 12),
              _legend(context),
              if (prices.stale) _footnote(context,
                  'Price data stale — controller hasn\'t refreshed the curve'),
            ],
          ],
        ),
      ),
    );
  }

  Widget _header(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final tt = Theme.of(context).textTheme;
    return Row(
      children: [
        Text('PRICES & CONSUMPTION',
            style: tt.labelSmall?.copyWith(
                color: cs.onSurfaceVariant, letterSpacing: 1.4)),
        const Spacer(),
        Text('day-ahead',
            style: tt.labelSmall?.copyWith(color: cs.onSurfaceVariant)),
      ],
    );
  }

  Widget _readout(BuildContext context, EnergyPrices prices, EnergyHistoryData? history) {
    final tt = Theme.of(context).textTheme;
    final cs = Theme.of(context).colorScheme;
    final now = DateTime.now();
    final cur = prices.currentAt(now);
    final costCents = prices.consumptionCostCents(history);

    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // Top-left: aggregated cost of consumed energy.
        Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              crossAxisAlignment: CrossAxisAlignment.baseline,
              textBaseline: TextBaseline.alphabetic,
              children: [
                Text(
                  costCents == null ? '—' : '€${(costCents / 100).toStringAsFixed(2)}',
                  style: tt.headlineMedium?.copyWith(
                      fontWeight: FontWeight.w700, color: cs.onSurface),
                ),
              ],
            ),
            Text('consumption cost',
                style: tt.bodySmall?.copyWith(color: cs.onSurfaceVariant)),
          ],
        ),
        const Spacer(),
        // Top-right: current spot price.
        Column(
          crossAxisAlignment: CrossAxisAlignment.end,
          children: [
            Text(
              cur != null ? '${cur.ctPerKwh.toStringAsFixed(1)} ct/kWh' : '— ct/kWh',
              style: tt.titleMedium?.copyWith(
                  fontWeight: FontWeight.w700, color: cs.onSurface),
            ),
            Text('now · Ø ${prices.avgCt.toStringAsFixed(1)}',
                style: tt.bodySmall?.copyWith(color: cs.onSurfaceVariant)),
          ],
        ),
      ],
    );
  }

  Widget _chart(EnergyPrices prices, EnergyHistoryData? history) {
    return AspectRatio(
      aspectRatio: 1.9,
      child: LayoutBuilder(builder: (context, _) {
        final cs = Theme.of(context).colorScheme;
        return CustomPaint(
          painter: _PriceChartPainter(
            prices: prices,
            history: history,
            now: DateTime.now(),
            axisColor: cs.onSurfaceVariant.withValues(alpha: 0.28),
            labelColor: cs.onSurfaceVariant,
          ),
        );
      }),
    );
  }

  Widget _legend(BuildContext context) {
    return Wrap(
      spacing: 16, runSpacing: 6, alignment: WrapAlignment.center,
      children: [
        _swatch(context, _priceColor, 'Price (ct/kWh)'),
        _lineSwatch(context, _consumeColor, 'Consumption'),
      ],
    );
  }

  Widget _swatch(BuildContext context, Color c, String label) {
    final tt = Theme.of(context).textTheme;
    final cs = Theme.of(context).colorScheme;
    return Row(mainAxisSize: MainAxisSize.min, children: [
      Container(width: 12, height: 12, decoration:
          BoxDecoration(color: c, borderRadius: BorderRadius.circular(3))),
      const SizedBox(width: 6),
      Text(label, style: tt.bodySmall?.copyWith(color: cs.onSurfaceVariant)),
    ]);
  }

  Widget _lineSwatch(BuildContext context, Color c, String label) {
    final tt = Theme.of(context).textTheme;
    final cs = Theme.of(context).colorScheme;
    return Row(mainAxisSize: MainAxisSize.min, children: [
      Container(width: 14, height: 3, color: c),
      const SizedBox(width: 6),
      Text(label, style: tt.bodySmall?.copyWith(color: cs.onSurfaceVariant)),
    ]);
  }

  Widget _placeholder(BuildContext context, bool loading) {
    final cs = Theme.of(context).colorScheme;
    final tt = Theme.of(context).textTheme;
    return SizedBox(
      height: 120,
      child: Center(
        child: loading
            ? const SizedBox(
                width: 22, height: 22, child: CircularProgressIndicator(strokeWidth: 2))
            : Text('PRICE DATA UNAVAILABLE',
                style: tt.labelSmall?.copyWith(
                    color: cs.onSurfaceVariant, letterSpacing: 1.2)),
      ),
    );
  }

  Widget _footnote(BuildContext context, String text) {
    final cs = Theme.of(context).colorScheme;
    final tt = Theme.of(context).textTheme;
    return Padding(
      padding: const EdgeInsets.only(top: 10),
      child: Text(text, style: tt.bodySmall?.copyWith(color: cs.onSurfaceVariant)),
    );
  }
}

// ── Painter ────────────────────────────────────────────────────────────────
class _PriceChartPainter extends CustomPainter {
  _PriceChartPainter({
    required this.prices,
    required this.history,
    required this.now,
    required this.axisColor,
    required this.labelColor,
  });

  final EnergyPrices prices;
  final EnergyHistoryData? history;
  final DateTime now;
  final Color axisColor;
  final Color labelColor;

  static const _padBottom = 18.0;
  static const _padTop = 8.0;
  static const _padLeft = 28.0; // room for the ct/kWh axis labels

  @override
  void paint(Canvas canvas, Size size) {
    final pts = prices.points;
    if (pts.isEmpty) return;

    final plotH = size.height - _padBottom - _padTop;
    final plotW = size.width - _padLeft;

    final resMs = prices.resolution.inMilliseconds;
    final coverStart = pts.first.time.millisecondsSinceEpoch;
    final coverEnd = pts.last.time.millisecondsSinceEpoch + resMs;

    // Window to ~now ±12h so past consumption and upcoming prices share the view.
    const half = 12 * 3600 * 1000;
    final nowMs = now.millisecondsSinceEpoch;
    var startMs = nowMs - half < coverStart ? coverStart : nowMs - half;
    var endMs = nowMs + half > coverEnd ? coverEnd : nowMs + half;
    if (endMs <= startMs) { startMs = coverStart; endMs = coverEnd; }
    final span = (endMs - startMs).toDouble();
    double x(int ms) => _padLeft + plotW * (ms - startMs) / span;

    // Price Y scale — include 0, round the top (and bottom, if negative) to a
    // nice value so the gridline labels are tidy.
    final rawHi = prices.maxCt > 0 ? prices.maxCt : 1.0;
    final rawLo = prices.minCt < 0 ? prices.minCt : 0.0;
    final step = _niceStep((rawHi - rawLo) / 4);
    final hi = (rawHi / step).ceil() * step;
    final lo = (rawLo / step).floor() * step;
    final range = (hi - lo) <= 0 ? 1.0 : (hi - lo);
    double yPrice(double ct) => _padTop + plotH * (1 - (ct - lo) / range);

    // Horizontal gridlines + ct/kWh labels.
    final tp = TextPainter(textDirection: TextDirection.ltr);
    final gridPaint = Paint()..color = axisColor..strokeWidth = 1;
    for (var v = lo; v <= hi + 0.001; v += step) {
      final gy = yPrice(v);
      canvas.drawLine(Offset(_padLeft, gy), Offset(size.width, gy),
          gridPaint..color = axisColor.withValues(alpha: v == 0 ? 0.5 : 0.22));
      tp
        ..text = TextSpan(
            text: step >= 1 ? v.toStringAsFixed(0) : v.toStringAsFixed(1),
            style: TextStyle(color: labelColor, fontSize: 9))
        ..layout();
      tp.paint(canvas, Offset(_padLeft - tp.width - 4, gy - tp.height / 2));
    }
    final zeroY = yPrice(0);

    // Price bars (single colour; readable against the labelled axis).
    for (final p in pts) {
      final x0 = x(p.time.millisecondsSinceEpoch);
      final x1 = x(p.time.millisecondsSinceEpoch + resMs);
      if (x1 < _padLeft || x0 > size.width) continue; // outside the window
      final yv = yPrice(p.ctPerKwh);
      final top = p.ctPerKwh >= 0 ? yv : zeroY;
      final bot = p.ctPerKwh >= 0 ? zeroY : yv;
      canvas.drawRect(Rect.fromLTRB(x0 + 0.5, top, x1 - 0.5, bot),
          Paint()..color = _priceColor.withValues(alpha: 0.50));
    }

    // Consumption overlay (its own scale), only over covered time.
    final h = history;
    if (h != null && h.points.isNotEmpty) {
      var consMax = 0.0;
      for (final hp in h.points) {
        if (hp.consumptionW > consMax) consMax = hp.consumptionW;
      }
      if (consMax > 0) {
        final baseY = _padTop + plotH;
        final line = Path();
        final fill = Path();
        var started = false;
        double firstX = 0, lastX = 0;
        for (final hp in h.points) {
          final ms = hp.time.millisecondsSinceEpoch;
          if (ms < startMs || ms > endMs) continue;
          final px = x(ms);
          final py = _padTop + plotH * (1 - 0.85 * (hp.consumptionW / consMax));
          if (!started) {
            line.moveTo(px, py);
            fill..moveTo(px, baseY)..lineTo(px, py);
            firstX = px; started = true;
          } else {
            line.lineTo(px, py);
            fill.lineTo(px, py);
          }
          lastX = px;
        }
        if (started) {
          fill..lineTo(lastX, baseY)..lineTo(firstX, baseY)..close();
          canvas.drawPath(fill, Paint()..color = _consumeColor.withValues(alpha: 0.18));
          canvas.drawPath(
              line,
              Paint()
                ..color = _consumeColor
                ..style = PaintingStyle.stroke
                ..strokeWidth = 2
                ..strokeJoin = StrokeJoin.round
                ..isAntiAlias = true);
        }
      }
    }

    // "Now" marker + current price label.
    if (nowMs >= startMs && nowMs <= endMs) {
      final nx = x(nowMs);
      canvas.drawLine(Offset(nx, _padTop), Offset(nx, _padTop + plotH),
          Paint()..color = labelColor.withValues(alpha: 0.7)..strokeWidth = 1);
    }

    // X labels at each midnight + noon within the window.
    for (final p in pts) {
      final t = p.time;
      final ms = t.millisecondsSinceEpoch;
      if (ms < startMs || ms > endMs) continue;
      if (t.minute == 0 && (t.hour == 0 || t.hour == 12)) {
        final lx = x(ms);
        canvas.drawLine(Offset(lx, _padTop), Offset(lx, _padTop + plotH),
            Paint()..color = axisColor.withValues(alpha: 0.35)..strokeWidth = 1);
        tp
          ..text = TextSpan(
              text: t.hour == 0 ? '00:00' : '12:00',
              style: TextStyle(color: labelColor, fontSize: 9))
          ..layout();
        tp.paint(canvas, Offset(lx + 2, size.height - tp.height));
      }
    }
  }

  /// Round [v] up to a tidy 1/2/5 × 10^k step for the price axis.
  double _niceStep(double v) {
    if (v <= 0) return 1;
    var mag = 1.0;
    while (mag * 10 <= v) {
      mag *= 10;
    }
    for (final m in [1.0, 2.0, 5.0, 10.0]) {
      if (mag * m >= v) return mag * m;
    }
    return mag * 10;
  }

  @override
  bool shouldRepaint(_PriceChartPainter old) =>
      old.prices != prices || old.history != history || old.now != now;
}

